function uniquePathsIII(maze) {
  function isValid(row, col) {
    // check if the cell is within the maze
    if (row < 0 || row >= maze.length || col < 0 || col >= maze[0].length) {
      return false;
    }
    // check if the cell is an obstacle
    if (maze[row][col] === 1) {
      return false;
    }
    return true;
  }

  function dfs(row, col, count) {
    // if we have reached the bottom-right cell, return 1
    if (row === maze.length - 1 && col === maze[0].length - 1) {
      return 1;
    }
    // if the cell is not valid, return 0
    if (!isValid(row, col)) {
      return 0;
    }
    // mark the cell as visited
    maze[row][col] = 1;
    // recursively explore the neighboring cells
    return dfs(row - 1, col, count + 1) + dfs(row + 1, col, count + 1) + dfs(row, col - 1, count + 1) + dfs(row, col + 1, count + 1);
  }

  let startRow, startCol;
  // find the start position
  for (let i = 0; i < maze.length; i++) {
    for (let j = 0; j < maze[0].length; j++) {
      if (maze[i][j] === 0) {
        startRow = i;
        startCol = j;
        break;
      }
    }
    if (startRow !== undefined) {
      break;
    }
  }

  // call the dfs function
  return dfs(startRow, startCol, 0);
}

